CREATE OR REPLACE PROCEDURE purge_old_audit_logs(p_retention_days INT)
LANGUAGE plpgsql AS $$
DECLARE
    v_deleted_count INT;
BEGIN
    LOOP
        DELETE FROM audit_logs
        WHERE id IN (
            SELECT id FROM audit_logs
            WHERE created_at < NOW() - (p_retention_days || ' days')::INTERVAL
            LIMIT 10000
        );
        GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

        -- Commit batch to release locks and allow WAL cleanup
        COMMIT;

        EXIT WHEN v_deleted_count = 0;
    END LOOP;
END;
$$;
